// --- Helper: Normalize & Validate Saudi/Gulf Phone Numbers to E.164 ---
function validateAndNormalizePhone(phoneRaw) {
    if (!phoneRaw) {
        return { isValid: false, normalized: null };
    }

    // Clean non-digit characters except leading '+'
    let clean = String(phoneRaw).replace(/[^\d+]/g, '');

    // Convert Saudi local '05XXXXXXXX' to '+9665XXXXXXXX'
    if (/^05\d{8}$/.test(clean)) {
        clean = '+966' + clean.slice(1);
    }
    // Convert '9665XXXXXXXX' to '+9665XXXXXXXX'
    else if (/^9665\d{8}$/.test(clean)) {
        clean = '+' + clean;
    }
    // Convert '009665XXXXXXXX' to '+9665XXXXXXXX'
    else if (/^009665\d{8}$/.test(clean)) {
        clean = '+' + clean.slice(2);
    }

    // Validate E.164 format (+9665XXXXXXXX or general international +1-15 digits)
    const e164Regex = /^\+[1-9]\d{1,14}$/;
    const isValid = e164Regex.test(clean);

    return {
        isValid: isValid,
        normalized: isValid ? clean : null
    };
}

// --- Helper: Validate Email Format ---
function validateEmail(emailRaw) {
    if (!emailRaw) {
        return { isValid: false, normalized: null };
    }

    const clean = String(emailRaw).trim().toLowerCase();
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    const isValid = emailRegex.test(clean);

    return {
        isValid: isValid,
        normalized: isValid ? clean : null
    };
}

// --- Helper: Validate & Clean Name ---
function validateName(nameRaw) {
    if (!nameRaw) {
        return { isValid: false, normalized: null };
    }

    const clean = String(nameRaw).trim();
    const isValid = clean.length >= 2;

    return {
        isValid: isValid,
        normalized: isValid ? clean : null
    };
}

// --- Main n8n Node Execution (Looping over all incoming items) ---
const currentTimeIso = new Date().toISOString(); 
const currentTimestampSec = Math.floor(Date.now() / 1000); 

// Map over every incoming item in the array cleanly
return $input.all().map(item => {
    const inputPayload = item.json;

    // Extract potential source fields
    const mobileRaw = inputPayload['Phone number'];
    const emailRaw = inputPayload['Email'];
    const nameRaw = inputPayload['Name'];

    // 1. Run Validations
    const phoneRes = validateAndNormalizePhone(mobileRaw);
    const emailRes = validateEmail(emailRaw);
    const nameRes = validateName(nameRaw);

    // 2. Collect Validation Errors
    const validationErrors = [];
    if (mobileRaw && !phoneRes.isValid) {
        validationErrors.push("Invalid mobile phone format");
    }
    if (emailRaw && !emailRes.isValid) {
        validationErrors.push("Invalid email format");
    }
    if (nameRaw && !nameRes.isValid) {
        validationErrors.push("Invalid name string");
    }

    // 3. Return the restructured object formatted for n8n's expected JSON output
    return {
        json: {
            // Validation Metadata
            "is_valid_lead": phoneRes.isValid || emailRes.isValid,
            "validation_errors": validationErrors,

            // Group 1: Identity and Source
            "lead_id": inputPayload["lead_id"] || `LEAD-${currentTimestampSec}`,
            "source": inputPayload["source"] || "Google Forms",
            "campaign": inputPayload["campaign"] || "Al_Tilal_Q3_Awareness",
            "name": nameRes.normalized,
            "mobile": phoneRes.normalized,
            "email": emailRes.normalized,
            "city": inputPayload["city"] || "Riyadh",

            // Group 2: Buying Needs
            "interested_asset": inputPayload["interested_asset"] || null,
            "property_type": inputPayload["property_type"] || null,
            "budget_range": inputPayload["budget_range"] || null,
            "investment_purpose": inputPayload["investment_purpose"] || null,
            "individual_or_company": inputPayload["individual_or_company"] || null,
            "auction_experience": inputPayload["auction_experience"] || null,

            // Group 3: Readiness and Contact
            "purchase_readiness": inputPayload["purchase_readiness"] || null,
            "cash_or_financing_readiness": inputPayload["cash_or_financing_readiness"] || null,
            "timeline": inputPayload["timeline"] || null,
            "preferred_contact_method": inputPayload["preferred_contact_method"] || "WhatsApp",
            "consent_or_contact_status": inputPayload["consent_or_contact_status"] || "Pending",

            // Group 4: Workflow Record
            "created_date": inputPayload["created_date"] || currentTimeIso,
            "last_interaction": currentTimeIso,
            "qualification_status": "Pending_Qualification",
            "score": null,
            "reason": null,

            // Audit Trail
            "raw_payload": inputPayload
        }
    };
});

const originalData = $node["Data Validation and Extraction"].json;
const searchResult = $input.item.json;

const contactExists = searchResult && searchResult.id ? true : false;

return {
    // 1. Preserve ALL original validation data (including created_date)
  ...originalData,

  // 2. Attach CRM Lookup Metadata
  crm_lookup: {
    is_existing_contact: contactExists,
    hubspot_contact_id: contactExists ? searchResult.id : null,
    // If contact exists, preserve original CRM creation date; otherwise keep payload created_date
    created_date: contactExists 
      ? searchResult.properties.createdate || originalData.created_date 
      : originalData.created_date
  }
};

