// 1. Pull master payload from whichever state builder ran for this path.
// Chat/WhatsApp path -> "Build Master State"; Google Sheets path -> "Merge Fetched Data".
let masterState;
try { masterState = $node["Build Master State"].json; } catch (e) { masterState = null; }
if (!masterState || Object.keys(masterState).length === 0) {
  try { masterState = $node["Merge Fetched Data"].json; } catch (e2) { masterState = {}; }
}

// 2. Pull output from the AI Agent node
const agentOutput = $input.item.json;

// Extract structured fields safely
const structuredData = agentOutput.output || agentOutput;
const replyMessage = structuredData.reply_message || "تم استلام معلوماتك، شكراً لك.";
const extracted = structuredData.extracted_slots || {};

// 3. Deep copy master state to maintain immutability
const updatedState = JSON.parse(JSON.stringify(masterState));

// ============================================================================
// 4. APPLY SLOT DELTA UPDATES (Flat Canonical Schema)
// ============================================================================

if (extracted.property_type) {
  updatedState.property_type = extracted.property_type;
}
if (extracted.interested_asset) {
  updatedState.interested_asset = extracted.interested_asset;
}
if (extracted.budget_range && extracted.budget_range.min_sar !== null) {
  updatedState.budget_range = extracted.budget_range;
}
if (extracted.cash_or_financing_readiness) {
  updatedState.cash_or_financing_readiness = extracted.cash_or_financing_readiness;
}
if (extracted.timeline) {
  updatedState.timeline = extracted.timeline;
}
if (extracted.purchase_readiness) {
  updatedState.purchase_readiness = extracted.purchase_readiness;
}
if (extracted.investment_purpose) {
  updatedState.investment_purpose = extracted.investment_purpose;
}

// Update last interaction timestamp
updatedState.last_interaction = new Date().toISOString();

// Ensure a stable key for persistence (phone-first, else existing session_key)
updatedState.session_key = updatedState.session_key || updatedState.mobile || null;

// ============================================================================
// 5. EVALUATE QUALIFICATION / ESCALATION STATE
// ============================================================================

if (extracted.escalate_to_human) {
  updatedState.qualification_status = "Escalated_To_Human";
  updatedState.reason = extracted.escalation_reason || "Escalated by AI Agent";
} 
// Special Handling for Browsing / Informational Intent
else if (updatedState.timeline === "Browsing" || updatedState.purchase_readiness === "Informational") {
  updatedState.qualification_status = "Qualified";
  updatedState.reason = "Lead identified as market browser / low urgency.";
} 
else {
  // Evaluate core active buyer slots
  const isFullyQualified = 
    updatedState.property_type !== null &&
    updatedState.budget_range !== null &&
    updatedState.cash_or_financing_readiness !== null &&
    updatedState.timeline !== null;

  if (isFullyQualified) {
    updatedState.qualification_status = "Qualified";
    updatedState.reason = "All required buying and readiness slots populated.";
  } else {
    updatedState.qualification_status = "In_Progress_AI_Agent";
    updatedState.reason = "Awaiting remaining buyer slot fulfillment.";
  }
}

// ============================================================================
// 6. RETURN ENRICHED PAYLOAD FOR SWITCH NODE & MESSAGING
// ============================================================================
return {
  json: {
    ...updatedState,
    agent_reply_message: replyMessage
  }
};

// ============================================================================
// STAGE 4: PRIORITY SCORING ENGINE CODE NODE
// ============================================================================
// Defines priority tiers (P1, P2, P3, Disqualified) based on collected state attributes:
// - Budget (max_sar)
// - Financial Readiness (Cash_Ready vs Financing_Needed)
// - Purchasing Timeline (Immediate_Auction vs 1_Month / 3_Months vs Browsing)
// ============================================================================

const state = $input.first().json;

let score = 'P3';
let reason = '';

const maxBudget = state.budget_range?.max_sar || 0;
const isCash = state.cash_or_financing_readiness === 'Cash_Ready';
const isImmediate = state.timeline === 'Immediate_Auction';
const isFinancing = state.cash_or_financing_readiness === 'Financing_Needed';

// ----------------------------------------------------------------------------
// TIER 0: DISQUALIFIED LEAD
// Criteria: Budget below the minimum property starting bid threshold in the auction,
//           or explicit lack of buying intent.
// Action:   Do not route to active sales queue; tag for automated low-priority cleanup.
// ----------------------------------------------------------------------------
if (maxBudget > 0 && maxBudget < 300000) {
  score = 'Disqualified';
  reason = `Budget of ${maxBudget.toLocaleString()} SAR is below the minimum auction parcel threshold.`;
} 

// ----------------------------------------------------------------------------
// TIER 1: P1 (HOT LEAD / HIGH PRIORITY)
// Criteria: High budget (>= 1M SAR), liquid funds ready (Cash_Ready), and urgent 
//           intent to participate in the upcoming auction (Immediate_Auction).
// Action:   Immediate direct phone call or high-touch sales outreach before auction day.
// ----------------------------------------------------------------------------
else if (isImmediate && isCash && maxBudget >= 1500000) {
  score = 'P1';
  reason = `Hot buyer ready for immediate auction participation with cash budget of ${maxBudget.toLocaleString()} SAR.`;
} 
else if (isImmediate && (isCash || maxBudget >= 1000000)) {
  score = 'P1';
  reason = `High-intent buyer participating in upcoming auction with budget of ${maxBudget.toLocaleString()} SAR.`;
}

// ----------------------------------------------------------------------------
// TIER 2: P2 (QUALIFIED / MEDIUM PRIORITY)
// Criteria: Valid buyer who requires bank financing, or has an active purchasing 
//           horizon beyond the immediate auction (1 to 3 months).
// Action:   Standard sales follow-up to pre-qualify financing or send secondary listings.
// ----------------------------------------------------------------------------
else if (isFinancing || state.timeline === '1_Month' || state.timeline === '3_Months') {
  score = 'P2';
  reason = isFinancing 
    ? `Qualified buyer needing bank financing with budget of ${maxBudget.toLocaleString()} SAR.`
    : `Qualified buyer planning to purchase within ${state.timeline ? state.timeline.replace('_', ' ') : '1-3 months'}.`;
}

// ----------------------------------------------------------------------------
// TIER 3: P3 (NURTURE / LOW PRIORITY)
// Criteria: Casual browsers, price researchers, or long-term market monitoring leads
//           without immediate purchase timeline or clear budget bounds.
// Action:   Route to marketing automated nurture campaigns / newsletter updates.
// ----------------------------------------------------------------------------
else {
  score = 'P3';
  reason = `Market browser or long-term lead looking for general pricing information.`;
}

// ----------------------------------------------------------------------------
// RETURN UPDATED CANONICAL MASTER STATE
// ----------------------------------------------------------------------------
return {
  json: {
    ...state,
    score,
    reason,
    qualification_status: score === 'Disqualified' ? 'Disqualified' : 'Qualified',
    last_interaction: new Date().toISOString()
  }
};

// Unify Chat Trigger and WhatsApp Trigger into a common shape.
// Chat:  { action, sessionId, chatInput }
// WhatsApp: { messages:[{ from, text:{body} }], contacts:[{ profile:{name}, wa_id }] }
const j = $input.item.json;

let session_key = null;
let phone = null;
let chatInput = '';
let contact_name = null;

if (j.chatInput !== undefined || j.sessionId !== undefined) {
  // In-editor / public chat path
  chatInput = j.chatInput || '';
  session_key = j.sessionId || 'chat-session';
} else {
  // WhatsApp webhook path
  const msg = (j.messages && j.messages[0]) || {};
  const contact = (j.contacts && j.contacts[0]) || {};
  const from = msg.from || (contact && contact.wa_id) || null;
  phone = from ? ('+' + String(from).replace(/[^\d]/g, '')) : null;
  chatInput = (msg.text && msg.text.body) || j.chatInput || '';
  contact_name = (contact.profile && contact.profile.name) || null;
  session_key = phone || 'wa-unknown';
}

// Phone number when present, else fall back to the chat session id
if (phone) session_key = phone;

return { json: { session_key, phone, chatInput, contact_name } };

// 1. Pull directly by Node Name
const sessionItem = $node["Load Lead State"]?.json || {};
const hubspotItem = $node["Search contacts"]?.json || {};
const sessionTrigger = $node["When chat message received"]?.json || {};

// 2. Safely parse the nested state_json string
let stateData = {};
try {
  stateData = typeof sessionItem.state_json === 'string' 
    ? JSON.parse(sessionItem.state_json) 
    : (sessionItem.state_json || {});
} catch (e) {
  stateData = {};
}

// 3. Extract HubSpot properties safely
const hsProps = hubspotItem.properties || {};
const hsContactId = hubspotItem.id || hsProps.hs_object_id || stateData.crm_lookup?.hubspot_contact_id || null;

// Parse contact name
const firstName = hsProps.firstname || "";
const lastName = hsProps.lastname || "";
const fullName = (firstName + " " + lastName).trim() || stateData.name || sessionItem.contact_name || null;

// 4. Construct the merged Canonical Master State Object
const mergedCanonicalSchema = {
  // Identity & Meta Fields
  is_valid_lead: stateData.is_valid_lead ?? true,
  validation_errors: stateData.validation_errors || [],
  lead_id: stateData.lead_id || `LEAD-${Date.now()}`,
  session_key: sessionItem.session_key || stateData.session_key || sessionTrigger.sessionId,
  source: stateData.source || "WhatsApp/Chat",
  campaign: stateData.campaign || "Al_Tilal_Q3_Awareness",

  // Lead Profile (Merged from HubSpot + DB State)
  name: fullName,
  mobile: hsProps.phone || sessionItem.phone || stateData.mobile || "+201141524031",
  email: hsProps.email || stateData.email || null,
  city: stateData.city || "Riyadh",

  // Buying Intent & Qualification Slots
  interested_asset: stateData.interested_asset || null,
  property_type: stateData.property_type || null,
  budget_range: stateData.budget_range || null,
  investment_purpose: stateData.investment_purpose || null,
  individual_or_company: stateData.individual_or_company || null,
  auction_experience: stateData.auction_experience || null,
  purchase_readiness: stateData.purchase_readiness || null,
  cash_or_financing_readiness: stateData.cash_or_financing_readiness || null,
  timeline: stateData.timeline || null,

  // Communication & Status
  preferred_contact_method: stateData.preferred_contact_method || "WhatsApp",
  consent_or_contact_status: stateData.consent_or_contact_status || "Pending",
  qualification_status: sessionItem.qualification_status || stateData.qualification_status || "In_Progress_AI_Agent",
  score: stateData.score || null,
  reason: stateData.reason || "Awaiting remaining buyer slot fulfillment.",

  // Nested CRM Resolution Object
  crm_lookup: {
    is_existing_contact: Boolean(hsContactId),
    hubspot_contact_id: hsContactId,
    created_date: hsProps.createdate || stateData.crm_lookup?.created_date || stateData.created_date || new Date().toISOString()
  },

  // Timestamps & AI Interaction Details
  created_date: stateData.created_date || sessionItem.createdAt || new Date().toISOString(),
  last_interaction: sessionItem.last_interaction || stateData.last_interaction || new Date().toISOString(),
  chatInput: sessionTrigger.chatInput || null,
  agent_reply_message: stateData.agent_reply_message || null
};

return { json: mergedCanonicalSchema };

